//! Corrupt actual generated bytes, then invoke the production image constructor.
use super::*;

#[test]
fn missing_wrong_and_out_of_bounds_owned_receipts_are_rejected() {
    type Tick = g::Msg<39, ()>;
    type Steps = g::Seq<
        g::Roll<g::Seq<g::Send<0, 1, Tick>, g::Send<10, 3, Read>>>,
        g::Seq<g::Send<11, 4, Loan>, g::Seq<g::Send<4, 11, Loan>, g::Send<1, 2, OtherLoan>>>,
    >;
    let image = &RoleProjection::<1, Steps, 16>::IMAGE_REF;
    const N: usize = RoleProjection::<1, Steps, 16>::IMAGE_REF
        .columns()
        .blob_len();
    const MUTANTS: [(crate::global::role_program::RoleImageColumns, [u8; N]); 4] = {
        let image = &RoleProjection::<1, Steps, 16>::IMAGE_REF;
        let descriptor = RoleDescriptorRef::from_resident(image);
        let mut bytes = [0; N];
        let mut index = 0;
        while index < N {
            bytes[index] = descriptor.proof_byte_at(index);
            index += 1;
        }
        let columns = *image.columns();
        assert!(columns.owned_receipt_count == 1);
        let entry = columns.roll_entry_views().offset as usize;
        assert!(bytes[entry] == 10);
        let receipt = columns.owned_receipts().offset as usize;
        let mut out_of_bounds = bytes;
        out_of_bounds[receipt] = 255;
        out_of_bounds[receipt + 1] = 255;
        let mut wire_receive = bytes;
        wire_receive[receipt] = 0;
        wire_receive[receipt + 1] = 0;
        let mut missing_slice = bytes;
        index = entry + 3;
        while index < entry + 7 {
            missing_slice[index] = 0;
            index += 1;
        }
        let mut missing_columns = columns;
        missing_columns.owned_receipt_count = 0;
        [
            (columns, out_of_bounds),
            (columns, wire_receive),
            (columns, missing_slice),
            (missing_columns, missing_slice),
        ]
    };
    #[cfg(not(miri))]
    {
        use std::{format, string::String, vec::Vec};
        let descriptor = RoleDescriptorRef::from_resident(image);
        let mut generated = format!(
            "import Hibana.MainTheorems\n\ndef generatedOwnedRecoveryImage : Hibana.RustDescriptorImage := {}\n\ntheorem generatedOwnedRecoveryCatalogAccepted :\n  generatedOwnedRecoveryImage.ownedRecoveryIndexCheck = true := by decide\n",
            crate::test_support::lean_descriptor::descriptor_source(descriptor)
        );
        for (index, (columns, bytes)) in MUTANTS.iter().enumerate() {
            let bytes = bytes
                .iter()
                .map(|byte| format!("{byte}"))
                .collect::<Vec<String>>()
                .join(", ");
            generated.push_str(&format!("\ndef generatedOwnedRecoveryMutant{index} : Hibana.RustDescriptorImage :=\n  {{ generatedOwnedRecoveryImage with roleBytes := [{bytes}], ownedReceiptCount := {} }}\n\ntheorem generatedOwnedRecoveryMutant{index}Rejected :\n  generatedOwnedRecoveryMutant{index}.ownedRecoveryIndexCheck = false := by decide\n", columns.owned_receipt_count));
        }
        generated.push_str("\n#eval IO.println \"hibana Lean owned-recovery index proof passed images=5 rejection=4\"\n");
        let output = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("target/lean-proof");
        std::fs::create_dir_all(&output).unwrap();
        std::fs::write(output.join("OwnedRecoveryGenerated.lean"), generated).unwrap();
    }
    for (columns, malformed) in &MUTANTS {
        let result = std::panic::catch_unwind(|| {
            RoleImageRef::new(
                image.program(),
                image.role(),
                image.facts(),
                columns,
                malformed,
            )
        });
        assert!(result.is_err(), "a corrupted receipt index was published");
    }
}
